import skarstrom as sk

sim = sk.Simulation.new()
sim.info.title = 'Perez 2019 - Configuration C1'
sim.info.description = 'Four-step pressure swing adsorption cycle for CO2/N2 separation based on Perez et al. 2019, configuration C1. This is a standard PSA cycle configuration using 13X zeolite adsorbent. The cycle consists of feed, blowdown, evacuation, and pressurisation steps. During the feed step, a CO2/N2 mixture enters at the bottom of the bed and exits at the top. The blowdown step reduces pressure at the top outlet, followed by evacuation at the bottom to achieve deep vacuum conditions. Pressurisation occurs at the bottom inlet using the feed gas composition. This configuration represents a typical four-step PSA process for gas separation applications.'
sim.info.author = 'Sam Affleck'

# ---- fluid --------------------------------------------------------------------
sim.add_component('CarbonDioxide')
sim.add_component('Nitrogen')
sim.fluid.adsorbed_heat_capacity_mode = 0
sim.fluid.heat_of_adsorption_convention = 0
sim.fluid.adsorbed_heat_capacity['CarbonDioxide'] = 30.7
sim.fluid.adsorbed_heat_capacity['Nitrogen'] = 30.7

# ---- adsorbents -----------------------------------------------------------------
ads_13x = sim.add_adsorbent('13X', solid_density=1138.0252816422599, heat_capacity=900.0, thermal_conductivity=0.63, particle_void_fraction=0.35)
ads_13x.set_isotherm('extended_dual_site_langmuir_c', {
    'CarbonDioxide': {'m1': 2.768, 'b1': 3.934e-07, 'q1': 40980.0, 'm2': 2.758, 'b2': 1.256e-07, 'q2': 34190.0},
    'Nitrogen': {'m1': 2.768, 'b1': 3.134e-06, 'q1': 15710.0, 'm2': 2.758, 'b2': 3.134e-06, 'q2': 15720.0},
}, components=['CarbonDioxide', 'Nitrogen'])
ads_13x.set_rate_model('CarbonDioxide', 'ldf', 'macropore', tortuosity=3.0, macropore_void_fraction=0.35)
ads_13x.set_rate_model('Nitrogen', 'ldf', 'macropore', tortuosity=3.0, macropore_void_fraction=0.35)
ads_13x.heat_of_adsorption['CarbonDioxide'] = 30850.0
ads_13x.heat_of_adsorption['Nitrogen'] = 15930.0

# ---- column ----------------------------------------------------------------------
sim.bed.set_shape('cylinder', diameter=0.032)
sim.bed.ambient_temperature = 293.0
sim.bed.set_thermal_equilibrium('lte')
sim.bed.set_particle_heat_transfer('constant', particle_htc=100.0)
sim.bed.bottom_void.enabled = False
sim.bed.bottom_void.volume = 0.0001
sim.bed.bottom_void.resistance_coefficient = 0.0
sim.bed.top_void.enabled = False
sim.bed.top_void.volume = 0.0001
sim.bed.top_void.resistance_coefficient = 0.0
sim.wall.set_material('ss316l', density=7800.0, heat_capacity=502.0, thermal_conductivity=16.0)
sim.wall.thickness = 0.0031
sim.wall.set_boundary('zero_flux')

# ---- layers (feed end first) ------------------------------------------------------
layer_13x = sim.add_layer('13X', composition={'13X': 1.0}, momentum='kozeny_carman', length=0.3, cells=30, bed_void_fraction=0.41, particle_diameter=0.0015)
layer_13x.set_dispersion('ruthven', molecular_diffusion_coefficient=1.6e-05)
layer_13x.set_heat_dispersion('constant', heat_dispersion_coefficient=0.0903)
layer_13x.set_internal_heat_transfer('constant', internal_htc=8.6)
layer_13x.set_external_heat_transfer('constant', external_htc=10.0)

# ---- initial conditions --------------------------------------------------------
sim.initial_conditions.pressure = 100000.0
sim.initial_conditions.temperature = 298.0
sim.initial_conditions.wall_temperature = 298.0
sim.initial_conditions.velocity = 0.0
sim.initial_conditions.y['Nitrogen'] = 1.0
sim.initial_conditions.y['CarbonDioxide'] = 0.0

# ---- cycle -------------------------------------------------------------------------
sim.cycle.number_of_cycles = 250
sim.cycle.step_time_mode = 0
feed = sim.add_step('Feed', time=114.0)
feed.bottom.set_streams('inlet', [
    sk.Stream('Feed inlet', flow=sk.velocity(0.03198), y={'Nitrogen': 0.85, 'CarbonDioxide': 0.15}, temperature=298.0),
])
feed.top.set_pressure('outlet', 100000.0, y={'CarbonDioxide': 0.0, 'Nitrogen': 1.0}, temperature=293.0)
blowdown = sim.add_step('Blowdown', time=19.0)
blowdown.bottom.set_closed()
blowdown.top.set_pressure('outlet', sk.exponential(10700.0), y={'CarbonDioxide': 0.0, 'Nitrogen': 1.0}, temperature=293.0)
evacuation = sim.add_step('Evacuation', time=57.0)
evacuation.bottom.set_pressure('outlet', sk.exponential(3200.0), y={'CarbonDioxide': 0.0, 'Nitrogen': 1.0}, temperature=293.0)
evacuation.top.set_closed()
pressurisation = sim.add_step('Pressurisation', time=30.0)
pressurisation.bottom.set_pressure('inlet', sk.linear(100000.0), y={'Nitrogen': 0.85, 'CarbonDioxide': 0.15}, temperature=298.0)
pressurisation.top.set_closed()
sim.kpi.track('CarbonDioxide', feed=[feed.bottom['Feed inlet'], pressurisation.bottom], product=[evacuation.bottom])

# ---- solver, cyclic steady state, energy balance --------------------------------------
sim.settings.init_step = 1e-10
sim.settings.min_step = 1e-15
sim.settings.max_step = 2.0
sim.settings.reltol = 1e-06
sim.settings.nonlin_conv_coef = 0.1
sim.settings.max_order = 5
sim.settings.max_nonlin_iters = 15
sim.settings.max_conv_fails = 200
sim.settings.max_err_test_fails = 40
sim.settings.max_num_steps = 100000
sim.settings.max_iters_per_step = 50000
sim.settings.advection_scheme = 0
sim.settings.max_cycles_to_keep = 10
sim.settings.max_log_points_per_step = 200
sim.settings.acceleration_method = 0
sim.css.method = 3
sim.css.min_cycles = 100
sim.css.molar_absolute_tolerance = 0.0001
sim.css.molar_relative_tolerance = 0.0001
sim.css.mass_balance_tolerance = 0.005
sim.energy_balance.energy_balance_mode = 0
sim.energy_balance.isothermal_use_initial_temperature = True
sim.energy_balance.isothermal_temperature = 298.15


if __name__ == "__main__":
    import sys

    result = sim.run(cycles=int(sys.argv[1]) if len(sys.argv) > 1 else None)
    print(result.status, f"after {result.cycles_run} cycles")
    for k in sim.kpis(cycle=-1):
        print(f"{k.component}: purity {k.purity:.4f}, recovery {k.recovery:.4f}")
